class Solution {
public:
    int minimumNumbers(int num, int k) {
        if (num == 0) return 0;
        for (int m = 1; m <= 10; ++m) {
            long long s = (long long)m * k;
            if (s % 10 == num % 10 && s <= num) return m;
        }
        return -1;
    }
};
